// Auto Grading - Chấm điểm tự động
// So sánh answers của học sinh với answer key

const submission = $input.first().json;

// Answer key - Có thể load từ sheet khác
const ANSWER_KEY = {
  'Q1': 'A',
  'Q2': 'C',
  'Q3': 'B',
  'Q4': 'D',
  'Q5': 'A',
  'Q6': 'C',
  'Q7': 'B',
  'Q8': 'D',
  'Q9': 'A',
  'Q10': 'C'
};

const totalQuestions = Object.keys(ANSWER_KEY).length;
const pointsPerQuestion = 100 / totalQuestions;

// Parse student answers (format: Q1:A,Q2:B,Q3:C,...)
const studentAnswers = {};
if (submission.answers) {
  const pairs = submission.answers.split(',');
  pairs.forEach(pair => {
    const [question, answer] = pair.trim().split(':');
    studentAnswers[question] = answer?.trim();
  });
}

// Grade each question
let correctCount = 0;
const grading = [];

for (const [question, correctAnswer] of Object.entries(ANSWER_KEY)) {
  const studentAnswer = studentAnswers[question] || 'N/A';
  const isCorrect = studentAnswer.toUpperCase() === correctAnswer.toUpperCase();

  if (isCorrect) correctCount++;

  grading.push({
    question,
    correct_answer: correctAnswer,
    student_answer: studentAnswer,
    is_correct: isCorrect
  });
}

const score = (correctCount / totalQuestions) * 100;
const grade = score >= 90 ? 'A' : 
              score >= 80 ? 'B' : 
              score >= 70 ? 'C' : 
              score >= 60 ? 'D' : 'F';

const passed = score >= 50;

console.log(`Student: ${submission.student_name}`);
console.log(`Score: ${score.toFixed(1)}% (${correctCount}/${totalQuestions})`);
console.log(`Grade: ${grade}`);

return [{
  json: {
    ...submission,
    score: score.toFixed(1),
    grade,
    correct_count: correctCount,
    total_questions: totalQuestions,
    passed,
    grading_details: grading,
    graded_at: new Date().toISOString(),
    timezone: 'Asia/Ho_Chi_Minh'
  }
}];
